  `id` int(11) NOT NULL AUTO_INCREMENT,
  `date_ordered` date DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=366 DEFAULT CHARSET=utf8;

